const callUserApi = async () => {
  // Check if options exist in localStorage with TTL
  const CACHE_TTL_MS = 2 * 60 * 1000;
  const cachedOptions = localStorage.getItem('caseAssignedOptions');
  const cachedTs = parseInt(localStorage.getItem('caseAssignedOptions_ts') || '0', 10);
  const now = Date.now();
  if (cachedOptions && (now - cachedTs) < CACHE_TTL_MS) {
    component.data.values = JSON.parse(cachedOptions); // Use cached options
    console.log('Using cached caseAssignedOptions');
    return JSON.parse(cachedOptions);
  }
  
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }
  
    const baseUrl = window.location.hostname.includes('localhost')
    ? 'http://localhost:8081'
    : localStorage.getItem('baseUrl') || '';

  try {
    const response = await fetch(`${baseUrl}/case-definition/users`, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${token}`
      }
    });

    if (!response.ok) {
      throw new Error(`API call failed with status: ${response.status}`);
    }

    const data = await response.json();
    const userOptions = data.map(user => ({
      label: user.userId, // Use userId as the display label
      value: user.emailId, // Use userId as the unique value
    }));

    localStorage.setItem('caseAssignedOptions', JSON.stringify(userOptions));
    localStorage.setItem('caseAssignedOptions_ts', String(Date.now()));
    return userOptions;
  } catch (error) {
    console.error('Error calling the User API:', error);
  }
};

// Example of using the callUserApi function
callUserApi().then(userOptions => {
  if (userOptions) {
    component.data.values = userOptions; // Assign the fetched options to component's data
  }
});

const callApi = function() {
  const token = localStorage.getItem('keycloakToken');

  if (!token) {
    console.error('Token not found in localStorage');
    return;
  }

  // Get 'eventIds' from the URL parameters
  const urlParams = new URLSearchParams(window.location.search);
  const eventIds = urlParams.get('eventIds');

  if (!eventIds) {
    console.error('eventIds parameter not found in the URL');
    return;
  }

 const baseUrl = window.location.hostname.includes('localhost')
    ? 'http://localhost:8081'
    : localStorage.getItem('baseUrl') || '';
    
   // Encode the eventIds to be passed as a comma-separated string in the API request
  const encodedEventIds = encodeURIComponent(eventIds);

  // Make a single API call for all eventIds
  fetch(`${baseUrl}/case-definition/fault-history/eventIds?eventIds=${encodedEventIds}`, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${token}`
    }
  })
  .then(response => {
    if (!response.ok) {
      throw new Error(`API call failed with status: ${response.status}`);
    }
    return response.json();
  })
  .then(data => {
    if (Array.isArray(data)) {
      const mappedData = data.map(item => {
       // const creationDate = item.eventEnrichment?.creationDate || 'Default Value';

      const creationDate = item.startTime;        // Format the creation date to display only the date (YYYY-MM-DD)
      const formattedDate = creationDate !== 'Default Value' 
          ? new Date(creationDate).toLocaleString('en-GB', {
              day: '2-digit',
              month: '2-digit',
              year: 'numeric',
              hour: '2-digit',
              minute: '2-digit',
              hour12: true
            }).replace(/\//g, '-') // Replace "/" with "-" to get dd-MM-yyyy format
          : 'Default Value';

      const endDate = item.endTime;        // Format the creation date to display only the date (YYYY-MM-DD)
      const formattedEndDate = endDate !== 'Default Value' 
          ? new Date(endDate).toLocaleString('en-GB', {
              day: '2-digit',
              month: '2-digit',
              year: 'numeric',
              hour: '2-digit',
              minute: '2-digit',
              hour12: true
            }).replace(/\//g, '-') // Replace "/" with "-" to get dd-MM-yyyy format
          : 'Default Value';

  
        return {
          'subAsset': item.AssetDisplayName || 'Default Value',
          'subAssetName': item.assetName || 'Default Value',
          'eventName': item.events?.eventName || 'Default Value',
          'eventCategory': item.eventCategory?.name || 'Default Value',
          'TextFaultStartTimeDate': formattedDate, // Only date part
          'TextFaultEndTimeDate': endDate ? formattedEndDate : ''
        };
      });

      // Assign the mapped data to component.calculateValue
      //component.calculateValue = mappedData;
      
      instance.root.getComponent("eventsGrid").setValue(mappedData);
      // instance.root.getComponent("eventsGrid").triggerChange();
    } else {
      console.error('Data is not an array or is undefined:', data);
    }
  })
  .catch(error => {
    console.error('Error during API call:', error);
  });
};

// Call the function
callApi();

